using System;
using UnityEngine;
namespace RevolverMVP {
public sealed class BrassSkin:IDisposable {
readonly Texture2D disc,metal,wood,redWood,brass,hand,bullet;
static readonly Color ink=new Color(.025f,.019f,.008f),gold=new Color(.73f,.55f,.25f),light=new Color(.94f,.79f,.43f),dark=new Color(.27f,.19f,.065f);
public BrassSkin(){disc=Circle();metal=Gear();wood=Surface(false,false);redWood=Surface(true,false);brass=Surface(false,true);hand=Glove();bullet=Cartridge();}
public void Fill(Rect r,Color c){if(r.width<=0||r.height<=0)return;var old=GUI.color;GUI.color=old*c;GUI.DrawTexture(r,Texture2D.whiteTexture);GUI.color=old;}
void Tex(Rect r,Texture2D t,Color c){var old=GUI.color;GUI.color=old*c;GUI.DrawTexture(r,t,ScaleMode.StretchToFill,true);GUI.color=old;}
public void Disc(Vector2 p,float radius,Color c){if(radius>0)Tex(new Rect(p.x-radius,p.y-radius,radius*2,radius*2),disc,c);}
public void Line(Vector2 a,Vector2 b,float width,Color c){if((b-a).sqrMagnitude<.00001f)return;var m=GUI.matrix;RotateAt(Mathf.Atan2(b.y-a.y,b.x-a.x)*Mathf.Rad2Deg,a);Fill(new Rect(a.x,a.y-width/2,(b-a).magnitude,width),c);GUI.matrix=m;}
public static void RotateAt(float angle,Vector2 pivot){GUI.matrix=GUI.matrix*Matrix4x4.Translate(new Vector3(pivot.x,pivot.y,0))*Matrix4x4.Rotate(Quaternion.Euler(0,0,angle))*Matrix4x4.Translate(new Vector3(-pivot.x,-pivot.y,0));}
static Rect Inset(Rect r,float n){return new Rect(r.x+n,r.y+n,Mathf.Max(0,r.width-2*n),Mathf.Max(0,r.height-2*n));}
void Rivet(Vector2 p,float r){Disc(p+Vector2.one,r+1,ink);Disc(p,r,dark);Disc(p-new Vector2(.5f,.6f),r*.7f,gold);Line(p-new Vector2(r*.4f,r*.25f),p+new Vector2(r*.4f,r*.25f),1,dark);}
public void Panel(Rect r,bool red=false){if(r.width<4||r.height<4)return;float b=Mathf.Clamp(Mathf.Min(r.width,r.height)*.1f,3,9);Fill(new Rect(r.x+2,r.y+3,r.width,r.height),new Color(0,0,0,.8f));Fill(r,ink);Rect o=Inset(r,2);Tex(o,brass,Color.white);Fill(new Rect(o.x,o.y,o.width,1),light);Fill(new Rect(o.x,o.y,1,o.height),light);Fill(new Rect(o.x,o.yMax-2,o.width,2),dark);Fill(new Rect(o.xMax-2,o.y,2,o.height),dark);Rect n=Inset(r,b);Fill(n,ink);Tex(Inset(n,2),red?redWood:wood,Color.white);Fill(new Rect(n.x+2,n.yMax-3,n.width-4,1),new Color(.52f,.37f,.12f));if(r.width>55&&r.height>33){float d=b+4,s=Mathf.Clamp(b*.52f,2,4.5f);Rivet(new Vector2(r.x+d,r.y+d),s);Rivet(new Vector2(r.xMax-d,r.y+d),s);Rivet(new Vector2(r.x+d,r.yMax-d),s);Rivet(new Vector2(r.x+d,r.yMax-d),s);}}
public void Cylinder(Vector2 p,float radius,double rotation,bool[] loaded){if(radius<=0)return;Disc(p+new Vector2(3,5),radius,new Color(0,0,0,.8f));var m=GUI.matrix;RotateAt(-(float)rotation*Mathf.Rad2Deg,p);Tex(new Rect(p.x-radius,p.y-radius,2*radius,2*radius),metal,Color.white);GUI.matrix=m;for(int i=0;i<6;i++){double a=Math.PI/2+rotation+i*Math.PI/3;Vector2 s=p+new Vector2((float)Math.Cos(a),-(float)Math.Sin(a))*radius*.65f;float h=radius*.19f;Disc(s+Vector2.up,h+2,dark);Disc(s-Vector2.up,h+1,light);Disc(s,h-1,ink);Disc(s+Vector2.up*2,h-3,new Color(.12f,.082f,.025f));if(loaded!=null&&i<loaded.Length&&loaded[i]){Disc(s,h-3,gold);Disc(s-Vector2.one,h-6,light);Disc(s,h-8,new Color(.46f,.29f,.075f));Disc(s,Mathf.Max(2,h*.32f),gold);Disc(s-Vector2.one*.5f,Mathf.Max(1,h*.22f),light);}}Disc(p,radius*.235f,dark);Disc(p-Vector2.up,radius*.22f,light);Disc(p,radius*.20f,gold);for(int i=0;i<6;i++){float a=i*Mathf.PI/3;Rivet(p+new Vector2(Mathf.Cos(a),Mathf.Sin(a))*radius*.16f,Mathf.Max(1.5f,radius*.018f));}Disc(p,radius*.105f,ink);Disc(p,radius*.08f,new Color(.17f,.12f,.035f));}
public void Bullet(Vector2 p,float size,float angle=0){var m=GUI.matrix;RotateAt(angle,p);Tex(new Rect(p.x-size/2,p.y-size*.205f,size,size*.41f),bullet,Color.white);GUI.matrix=m;}
public void Hand(Vector2 fingertip,float scale=1){Tex(new Rect(fingertip.x-15*scale,fingertip.y-7*scale,128*scale,148*scale),hand,Color.white);}
public void Heartbeat(Rect r,float beatPhase,Color c){float cycle=beatPhase-Mathf.Floor(beatPhase),mid=r.y+r.height*.58f;Vector2 last=Vector2.zero;for(int i=0;i<88;i++){float u=i/87f,q=(u*3-cycle)%1;if(q<0)q+=1;float v=0;if(q>.33f&&q<.40f)v=.16f*Mathf.Sin((q-.33f)/.07f*Mathf.PI);else if(q>=.45f&&q<.49f)v=-.24f*(q-.45f)/.04f;else if(q>=.49f&&q<.53f)v=Mathf.Lerp(-.24f,.95f,(q-.49f)/.04f);else if(q>=.53f&&q<.59f)v=Mathf.Lerp(.95f,-.44f,(q-.53f)/.06f);else if(q>=.59f&&q<.65f)v=Mathf.Lerp(-.44f,0,(q-.59f)/.06f);Vector2 next=new Vector2(r.x+u*r.width,mid-v*r.height*.56f);if(i>0){Line(last,next,4,new Color(c.r,c.g*.6f,c.b,.12f));Line(last,next,1.3f,c);}last=next;}Disc(new Vector2(r.xMax,mid),2.6f,c);}
public void FearMeter(Rect r,float amount){Panel(r);Rect n=Inset(r,Mathf.Min(5,r.height*.15f));float w=n.width/16;int count=Mathf.CeilToInt(Mathf.Clamp01(amount)*16);for(int i=0;i<16;i++){Rect b=new Rect(n.x+i*w+1,n.y+1,Mathf.Max(1,w-2),n.height-2);Fill(b,i<count?new Color(.67f,.16f,.065f):new Color(.12f,.065f,.03f));if(i<count)Fill(new Rect(b.x+1,b.y+1,Mathf.Max(1,b.width*.35f),b.height-2),new Color(.98f,.45f,.22f));}}
static Texture2D New(int w,int h,string name){return new Texture2D(w,h,TextureFormat.RGBA32,false){name=name,filterMode=FilterMode.Point,wrapMode=TextureWrapMode.Clamp,hideFlags=HideFlags.DontSave};}
static float Noise(int x,int y){unchecked{uint v=(uint)(x*374761393+y*668265263+173);v=(v^(v>>13))*1274126177;return(v&65535)/65535f;}}
static Texture2D Circle(){var t=New(96,96,"Pixel disc");for(int y=0;y<96;y++)for(int x=0;x<96;x++){float dx=x-47.5f,dy=y-47.5f;t.SetPixel(x,y,dx*dx+dy*dy<48*48?Color.white:Color.clear);}t.Apply(false,true);return t;}
static Texture2D Surface(bool red,bool metal){var t=New(128,128,"Distressed brass and wood");t.wrapMode=TextureWrapMode.Repeat;for(int y=0;y<128;y++)for(int x=0;x<128;x++){float n=Noise(x,y),g=Mathf.Sin(y*.85f+Mathf.Sin(x*.07f)*.8f)*.025f;float v=(metal?.56f:.15f)+(n-.5f)*(metal?.14f:.055f)+g;if(n>.985f)v*=.35f;if(n<.012f)v+=metal?.13f:.04f;t.SetPixel(x,y,metal?new Color(v,v*.74f,v*.34f):red?new Color(v*1.7f,v*.55f,v*.20f):new Color(v,v*.67f,v*.20f));}t.Apply(false,true);return t;}
static Texture2D Gear(){var t=New(256,256,"Six-lobed brass cylinder");for(int y=0;y<256;y++)for(int x=0;x<256;x++){float dx=x-127.5f,dy=y-127.5f,r=Mathf.Sqrt(dx*dx+dy*dy),a=Mathf.Atan2(dy,dx);float edge=124-Mathf.Pow((1+Mathf.Cos(6*a))*.5f,9)*9;if(r>edge){t.SetPixel(x,y,Color.clear);continue;}float v=.65f+(dy-dx)*.00075f+(Noise(x,y)-.5f)*.13f+Mathf.Sin(r*1.8f)*.013f;if(r>edge-2)v=.18f;else if(r>edge-4)v=.90f;else if(r>edge-7)v=.49f;if(Noise(x/3,y/2)>.988f)v*=.6f;t.SetPixel(x,y,new Color(v,v*.78f,v*.37f));}t.Apply(false,true);return t;}
static Texture2D Cartridge(){var t=New(96,40,"Brass cartridge");for(int y=0;y<40;y++)for(int x=0;x<96;x++){float dy=Mathf.Abs(y-19.5f),half=x<7?17:x<70?13:13*Mathf.Sqrt(Mathf.Max(0,1-Mathf.Pow((x-70)/24f,2)));if(dy>half||x>94){t.SetPixel(x,y,Color.clear);continue;}float v=.5f+.37f*(1-dy/18)+(Noise(x,y)-.5f)*.05f;if(x<2||x==7||x==10||x==67||x==70||dy>half-1.5f)v=.21f;if(y>23&&y<27&&x>12&&x<65)v=.97f;t.SetPixel(x,y,new Color(v,v*.73f,v*.22f));}t.Apply(false,true);return t;}
static Texture2D Glove(){var t=New(128,148,"Gloved pointing hand");Vector2[] shape={new Vector2(8,6),new Vector2(17,2),new Vector2(27,8),new Vector2(46,37),new Vector2(53,36),new Vector2(48,23),new Vector2(56,18),new Vector2(66,22),new Vector2(76,39),new Vector2(82,35),new Vector2(91,40),new Vector2(99,60),new Vector2(112,77),new Vector2(112,99),new Vector2(127,130),new Vector2(86,147),new Vector2(63,119),new Vector2(50,104),new Vector2(33,89),new Vector2(22,70),new Vector2(12,51),new Vector2(12,40),new Vector2(20,34),new Vector2(29,43),new Vector2(39,61),new Vector2(39,48),new Vector2(21,22)};for(int y=0;y<148;y++)for(int x=0;x<128;x++){if(!Inside(new Vector2(x,y),shape)){t.SetPixel(x,147-y,Color.clear);continue;}bool edge=!Inside(new Vector2(x-2,y),shape)||!Inside(new Vector2(x+2,y),shape)||!Inside(new Vector2(x,y-2),shape)||!Inside(new Vector2(x,y+2),shape);float v=.55f+(x-y)*.0008f+(Noise(x,y)-.5f)*.08f;bool seam=(y>35&&y<66&&Mathf.Abs(x-(y*.55f+23))<1.5f)||(y>56&&y<91&&Mathf.Abs(x-(y*.55f+28))<1.5f)||(y>83&&y<112&&Mathf.Abs(x-(y*.5f+14))<1.5f);if(y>116)v*=.65f;t.SetPixel(x,147-y,edge||seam?ink:new Color(v,v*.75f,v*.30f));}t.Apply(false,true);return t;}
static bool Inside(Vector2 p,Vector2[] shape){bool yes=false;for(int i=0,j=shape.Length-1;i<shape.Length;j=i++){Vector2 a=shape[i],b=shape[j];if((a.y>p.y)!=(b.y>p.y)&&p.x<(b.x-a.x)*(p.y-a.y)/(b.y-a.y)+a.x)yes=!yes;}return yes;}
public void Dispose(){foreach(var t in new[]{disc,metal,wood,redWood,brass,hand,bullet})if(t){if(Application.isPlaying)UnityEngine.Object.Destroy(t);else UnityEngine.Object.DestroyImmediate(t);}}
}
}
